styles:
html { -webkit-tap-highlight-color: transparent; }
body { margin: 0px; font-family: -apple-system, BlinkMacSystemFont, "Helvetica Neue", Helvetica, "Segoe UI", Arial, Roboto, "PingFang SC", "Hiragino Sans GB", "Microsoft Yahei", sans-serif; }
a { text-decoration: none; }
button, input, textarea { color: inherit; font: inherit; }
[class*="van-"]:focus, a:focus, button:focus, input:focus, textarea:focus { outline: 0px; }
ol, ul { margin: 0px; padding: 0px; list-style: none; }
.van-ellipsis { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
.van-multi-ellipsis--l2 { -webkit-line-clamp: 2; }
.van-multi-ellipsis--l2, .van-multi-ellipsis--l3 { display: -webkit-box; overflow: hidden; text-overflow: ellipsis; -webkit-box-orient: vertical; }
.van-multi-ellipsis--l3 { -webkit-line-clamp: 3; }
.van-clearfix::after { display: table; clear: both; content: ""; }
[class*="van-hairline"]::after { position: absolute; box-sizing: border-box; content: " "; pointer-events: none; inset: -50%; border: 0px solid rgb(235, 237, 240); transform: scale(0.5); }
.van-hairline, .van-hairline--bottom, .van-hairline--left, .van-hairline--right, .van-hairline--surround, .van-hairline--top, .van-hairline--top-bottom { position: relative; }
.van-hairline--top::after { border-top-width: 1px; }
.van-hairline--left::after { border-left-width: 1px; }
.van-hairline--right::after { border-right-width: 1px; }
.van-hairline--bottom::after { border-bottom-width: 1px; }
.van-hairline--top-bottom::after, .van-hairline-unset--top-bottom::after { border-width: 1px 0px; }
.van-hairline--surround::after { border-width: 1px; }
@-webkit-keyframes van-slide-up-enter { 
  0% { transform: translate3d(0px, 100%, 0px); }
}
@keyframes van-slide-up-enter { 
  0% { transform: translate3d(0px, 100%, 0px); }
}
@-webkit-keyframes van-slide-up-leave { 
  100% { transform: translate3d(0px, 100%, 0px); }
}
@keyframes van-slide-up-leave { 
  100% { transform: translate3d(0px, 100%, 0px); }
}
@-webkit-keyframes van-slide-down-enter { 
  0% { transform: translate3d(0px, -100%, 0px); }
}
@keyframes van-slide-down-enter { 
  0% { transform: translate3d(0px, -100%, 0px); }
}
@-webkit-keyframes van-slide-down-leave { 
  100% { transform: translate3d(0px, -100%, 0px); }
}
@keyframes van-slide-down-leave { 
  100% { transform: translate3d(0px, -100%, 0px); }
}
@-webkit-keyframes van-slide-left-enter { 
  0% { transform: translate3d(-100%, 0px, 0px); }
}
@keyframes van-slide-left-enter { 
  0% { transform: translate3d(-100%, 0px, 0px); }
}
@-webkit-keyframes van-slide-left-leave { 
  100% { transform: translate3d(-100%, 0px, 0px); }
}
@keyframes van-slide-left-leave { 
  100% { transform: translate3d(-100%, 0px, 0px); }
}
@-webkit-keyframes van-slide-right-enter { 
  0% { transform: translate3d(100%, 0px, 0px); }
}
@keyframes van-slide-right-enter { 
  0% { transform: translate3d(100%, 0px, 0px); }
}
@-webkit-keyframes van-slide-right-leave { 
  100% { transform: translate3d(100%, 0px, 0px); }
}
@keyframes van-slide-right-leave { 
  100% { transform: translate3d(100%, 0px, 0px); }
}
@-webkit-keyframes van-fade-in { 
  0% { opacity: 0; }
  100% { opacity: 1; }
}
@keyframes van-fade-in { 
  0% { opacity: 0; }
  100% { opacity: 1; }
}
@-webkit-keyframes van-fade-out { 
  0% { opacity: 1; }
  100% { opacity: 0; }
}
@keyframes van-fade-out { 
  0% { opacity: 1; }
  100% { opacity: 0; }
}
@-webkit-keyframes van-rotate { 
  0% { transform: rotate(0deg); }
  100% { transform: rotate(1turn); }
}
@keyframes van-rotate { 
  0% { transform: rotate(0deg); }
  100% { transform: rotate(1turn); }
}
.van-fade-enter-active { animation: 0.3s ease-out 0s 1 normal both running van-fade-in; }
.van-fade-leave-active { animation: 0.3s ease-in 0s 1 normal both running van-fade-out; }
.van-slide-up-enter-active { animation: 0.3s ease-out 0s 1 normal both running van-slide-up-enter; }
.van-slide-up-leave-active { animation: 0.3s ease-in 0s 1 normal both running van-slide-up-leave; }
.van-slide-down-enter-active { animation: 0.3s ease-out 0s 1 normal both running van-slide-down-enter; }
.van-slide-down-leave-active { animation: 0.3s ease-in 0s 1 normal both running van-slide-down-leave; }
.van-slide-left-enter-active { animation: 0.3s ease-out 0s 1 normal both running van-slide-left-enter; }
.van-slide-left-leave-active { animation: 0.3s ease-in 0s 1 normal both running van-slide-left-leave; }
.van-slide-right-enter-active { animation: 0.3s ease-out 0s 1 normal both running van-slide-right-enter; }
.van-slide-right-leave-active { animation: 0.3s ease-in 0s 1 normal both running van-slide-right-leave; }
.van-overlay { position: fixed; top: 0px; left: 0px; z-index: 1; width: 100%; height: 100%; background-color: rgba(0, 0, 0, 0.7); }
.van-info { position: absolute; top: 0px; right: 0px; box-sizing: border-box; min-width: 16px; padding: 0px 3px; color: rgb(255, 255, 255); font-weight: 500; font-size: 12px; font-family: Avenir-Heavy, "PingFang SC", "Helvetica Neue", Arial, sans-serif; line-height: 14px; text-align: center; background-color: rgb(238, 10, 36); border: 1px solid rgb(255, 255, 255); border-radius: 16px; transform: translate(50%, -50%); transform-origin: 100% center; }
.van-info--dot { width: 8px; min-width: 0px; height: 8px; background-color: rgb(238, 10, 36); border-radius: 100%; }
.van-sidebar-item { position: relative; display: block; box-sizing: border-box; padding: 20px 12px; overflow: hidden; color: rgb(50, 50, 51); font-size: 14px; line-height: 20px; overflow-wrap: break-word; background-color: rgb(247, 248, 250); cursor: pointer; user-select: none; }
.van-sidebar-item:active { background-color: rgb(242, 243, 245); }
.van-sidebar-item__text { position: relative; display: inline-block; }
.van-sidebar-item:not(:last-child)::after { border-bottom-width: 1px; }
.van-sidebar-item--select { color: rgb(50, 50, 51); font-weight: 500; }
.van-sidebar-item--select, .van-sidebar-item--select:active { background-color: rgb(255, 255, 255); }
.van-sidebar-item--select::before { position: absolute; top: 50%; left: 0px; width: 4px; height: 16px; background-color: rgb(238, 10, 36); transform: translateY(-50%); content: ""; }
.van-sidebar-item--disabled { color: rgb(200, 201, 204); cursor: not-allowed; }
.van-sidebar-item--disabled:active { background-color: rgb(247, 248, 250); }
