.van-icon__image { width: 1em; height: 1em; object-fit: contain; }
.van-tabbar-item { display: flex; -webkit-box-flex: 1; flex: 1 1 0%; -webkit-box-orient: vertical; -webkit-box-direction: normal; flex-direction: column; -webkit-box-align: center; align-items: center; -webkit-box-pack: center; justify-content: center; color: rgb(100, 101, 102); font-size: 12px; line-height: 1; cursor: pointer; }
.van-tabbar-item__icon { position: relative; margin-bottom: 5px; font-size: 18px; }
.van-tabbar-item__icon .van-icon { display: block; min-width: 1em; }
.van-tabbar-item__icon img { display: block; height: 18px; }
.van-tabbar-item--active { color: rgb(25, 137, 250); }
.van-tabbar-item .van-info { margin-top: 2px; }
.van-step { position: relative; -webkit-box-flex: 1; flex: 1 1 0%; color: rgb(150, 151, 153); font-size: 14px; }
.van-step__circle { display: block; width: 5px; height: 5px; background-color: rgb(150, 151, 153); border-radius: 50%; }
.van-step__line { position: absolute; background-color: rgb(235, 237, 240); transition: background-color 0.3s; }
.van-step--horizontal { float: left; }
.van-step--horizontal:first-child .van-step__title { margin-left: 0px; transform: none; }
.van-step--horizontal:last-child { position: absolute; right: 1px; width: auto; }
.van-step--horizontal:last-child .van-step__title { margin-left: 0px; transform: none; }
.van-step--horizontal:last-child .van-step__circle-container { right: -9px; left: auto; }
.van-step--horizontal .van-step__circle-container { position: absolute; top: 30px; left: -8px; z-index: 1; padding: 0px 8px; background-color: rgb(255, 255, 255); transform: translateY(-50%); }
.van-step--horizontal .van-step__title { display: inline-block; margin-left: 3px; font-size: 12px; transform: translateX(-50%); }
@media (max-width: 321px) {
  .van-step--horizontal .van-step__title { font-size: 11px; }
}
